nd-position:center;color:#fff}.e807-testimonials .e807-container>div{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}.e807-testimonials article{background:var(--e807-yellow);color:#111;padding:28px;min-height:190px}.e807-testimonials small{font-weight:700}.e807-testimonials p{line-height:1.6}.e807-knowledge{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.e807-knowledge article{position:relative}.e807-knowledge img{width:100%;height:290px;object-fit:cover}.e807-knowledge time{position:absolute;top:10px;left:10px;background:var(--e807-orange);color:#fff;padding:7px 12px;text-align:center;font-size:24px;font-weight:800}.e807-knowledge h3{font-size:19px}.e807-knowledge p{color:#666;line-height:1.6}.e807-brands{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}.e807-brands span{display:grid;place-items:center;min-height:85px;background:#fff;border:1px solid var(--e807-border);font-size:22px;font-weight:900}.e807-policy{background:var(--e807-yellow);padding:24px 0}.e807-policy .e807-container{display:grid;grid-template-columns:auto repeat(4,1fr);align-items:center;gap:25px}.e807-policy .e807-container>b{font-size:26px}.e807-policy span{display:grid;grid-template-columns:45px 1fr;align-items:center}.e807-policy i{grid-row:span 2;font-size:32px}.e807-policy small{display:block}.e807-footer{background:#050505;color:#fff;padding-top:65px}.e807-footer-grid{display:grid;grid-template-columns:1.4fr repeat(3,1fr) 1.2fr;gap:38px}.e807-footer h2,.e807-footer h3{color:var(--e807-yellow)}.e807-footer p,.e807-footer a,.e807-footer small{color:#ddd;line-height:1.7;overflow-wrap:anywhere}.e807-footer p i{color:var(--e807-yellow);width:24px}.e807-footer nav a{display:block;text-decoration:none;margin:7px 0}.e807-footer section strong{display:block;color:var(--e807-yellow);font-size:24px;margin:7px 0}.e807-market span{display:inline-grid;place-items:center;background:var(--e807-yellow);color:#111;width:38px;height:38px;border-radius:9px;margin-right:7px;font-weight:900}.e807-copy{border-top:1px solid #333;margin-top:45px;padding:18px;text-align:center;color:#aaa}.e807-content,.e807-listing{padding:50px 0}.e807-listing-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
